BEGIN;SET LOCAL statement_timeout='45min';SET LOCAL lock_timeout='30s';
SELECT set_config('yuzhou.run', :'run', true),set_config('yuzhou.db', :'db', true);
DO $$BEGIN IF current_database()<>current_setting('yuzhou.db') OR current_database()!~'^jinhu_hr_migration_lab_'THEN RAISE EXCEPTION'unsafe target';END IF;IF EXISTS(SELECT 1 FROM migration_batch WHERE run_id=current_setting('yuzhou.run'))THEN RAISE EXCEPTION'duplicate run';END IF;END$$;
CREATE TEMP TABLE sm(j jsonb);CREATE TEMP TABLE si(j jsonb);CREATE TEMP TABLE sf(j jsonb);CREATE TEMP TABLE st(j jsonb);CREATE TEMP TABLE sc(j jsonb);CREATE TEMP TABLE sp(j jsonb);COPY sm FROM :'memberships_path';COPY si FROM :'items_path';COPY sf FROM :'formulas_path';COPY st FROM :'tax_path';COPY sc FROM :'closes_path';COPY sp FROM :'payslips_path';
DO $$BEGIN IF(SELECT count(*)FROM sm)<>647 OR(SELECT count(*)FROM si)<>711 OR(SELECT count(*)FROM sf)<>244 OR(SELECT count(*)FROM st)<>9 OR(SELECT count(*)FROM sc)<>1431 OR(SELECT sum((j->>'sourceMultiplicity')::int)FROM sp)<>46092 THEN RAISE EXCEPTION'source count drift';END IF;END$$;
CREATE TEMP TABLE before_hash AS SELECT(SELECT encode(digest(COALESCE(string_agg(id::text||employment_status,''ORDER BY id),''),'sha256'),'hex')FROM hr_employee)employee,(SELECT encode(digest(COALESCE(string_agg(id::text||legacy_id,''ORDER BY id),''),'sha256'),'hex')FROM hr_employee_insurance_period)t3,(SELECT encode(digest(COALESCE(string_agg(id::text||status,''ORDER BY id),''),'sha256'),'hex')FROM hr_payroll_run)runs,(SELECT encode(digest(COALESCE(string_agg(id::text||status,''ORDER BY id),''),'sha256'),'hex')FROM hr_payslip)slips;
INSERT INTO migration_batch(run_id,source_system,source_snapshot_sha256,target_database,phase,status,tool_version,started_at)VALUES(:'run','yuzhou-v10',:'snap',:'db','load','running','t4-loader-v1',now());
INSERT INTO hr_payroll_legacy_batch(tenant_id,park_id,batch_code,source_backup_hash,catalog_hash,manifest_hash,source_row_count,status,remark)VALUES(:'tenant',:'park',:'run',:'snap',:'catalog',:'mh',46092,'unpublished','T4 run='||:'run');
INSERT INTO hr_payroll_book(tenant_id,park_id,legacy_scheme,book_name,source_hash,remark)SELECT :'tenant',:'park',n,'玉舟账套'||n,encode(digest(n::text,'sha256'),'hex'),'T4 run='||:'run' FROM generate_series(1,35)n;
INSERT INTO hr_payroll_item_definition(tenant_id,park_id,book_id,legacy_item_name,item_code,remark)SELECT :'tenant',:'park',b.id,j->'source'->>'itemname',upper(j->'source'->>'itemname'),'T4 run='||:'run'FROM si JOIN hr_payroll_book b ON b.legacy_scheme=(j->'source'->>'scheme')::int AND b.remark='T4 run='||:'run';
INSERT INTO hr_payroll_item_version(tenant_id,park_id,item_definition_id,version_no,display_name,value_type,legacy_item_type,legacy_add_or_sub,item_category,decimal_scale,sort_no,enabled,source_hash,remark)SELECT :'tenant',:'park',d.id,1,j->'source'->>'description',CASE j->'source'->>'datatype'WHEN'数值'THEN'decimal'WHEN'日期'THEN'date'ELSE'text'END,j->'source'->>'itemtype',j->'source'->>'addorsub',CASE j->'source'->>'addorsub'WHEN'增加项'THEN'earning'WHEN'减少项'THEN'deduction'WHEN'自动'THEN'summary'ELSE'unclassified'END,CASE WHEN j->'source'->>'datatype'='数值'THEN LEAST(4,COALESCE((j->'source'->>'declen')::int,2))END,COALESCE((j->'source'->>'myorder')::int,0),true,j->>'sourceRowSha256','T4 run='||:'run'FROM si JOIN hr_payroll_book b ON b.legacy_scheme=(j->'source'->>'scheme')::int AND b.remark='T4 run='||:'run'JOIN hr_payroll_item_definition d ON d.book_id=b.id AND d.legacy_item_name=j->'source'->>'itemname';
INSERT INTO hr_payroll_formula_version(tenant_id,park_id,book_id,item_version_id,legacy_formula_id,version_no,raw_expression,raw_condition,expression_hash,parse_status,dependency_codes,calculation_order,remark)SELECT :'tenant',:'park',b.id,v.id,(j->'source'->>'id')::int,1,j->'source'->>'expression',NULLIF(j->'source'->>'cit',''),j->'lexicalProfile'->>'expressionSha256','manual_review','[]',COALESCE((j->'source'->>'myorder')::int,1),'T4 run='||:'run'FROM sf JOIN hr_payroll_book b ON b.legacy_scheme=(j->'source'->>'scheme')::int AND b.remark='T4 run='||:'run'LEFT JOIN hr_payroll_item_definition d ON d.book_id=b.id AND d.legacy_item_name=j->'source'->>'itemname'LEFT JOIN hr_payroll_item_version v ON v.item_definition_id=d.id;
INSERT INTO hr_payroll_book_period(tenant_id,park_id,book_id,period_month,legacy_close_state,source_hash,remark)SELECT :'tenant',:'park',b.id,make_date((j->'source'->>'year')::int,(j->'source'->>'month')::int,1),(j->'source'->>'closestate')::int,j->>'sourceRowSha256','T4 run='||:'run'FROM sc JOIN hr_payroll_book b ON b.legacy_scheme=(j->'source'->>'scheme')::int AND b.remark='T4 run='||:'run';
CREATE TEMP TABLE em AS SELECT employee_code,min(id::text)::uuid id,count(*)n FROM hr_employee WHERE tenant_id=:'tenant'AND park_id=:'park'AND NOT is_deleted GROUP BY employee_code;
INSERT INTO hr_payroll_book_membership(tenant_id,park_id,book_id,employee_id,legacy_membership_id,legacy_employee_hash,mapping_status,source_hash,remark)SELECT :'tenant',:'park',b.id,CASE WHEN em.n=1 THEN em.id END,(j->'source'->>'id')::int,encode(digest(j->'source'->>'person','sha256'),'hex'),CASE WHEN em.n=1 THEN'mapped'ELSE'employee_unmapped'END,j->>'sourceRowSha256','T4 run='||:'run'FROM sm JOIN hr_payroll_book b ON b.legacy_scheme=(j->'source'->>'scheme')::int AND b.remark='T4 run='||:'run'LEFT JOIN em ON em.employee_code=j->'source'->>'person';
INSERT INTO hr_payroll_tax_rule_version(tenant_id,park_id,legacy_tax_id,base_amount,lower_limit,upper_limit,tax_percent,offset_amount,source_hash,remark)SELECT :'tenant',:'park',(j->'source'->>'id')::int,NULLIF(j->'source'->'base'->>'decimal','')::numeric,NULLIF(j->'source'->'limit1'->>'decimal','')::numeric,NULLIF(j->'source'->'limit2'->>'decimal','')::numeric,NULLIF(j->'source'->'taxpercent'->>'decimal','')::numeric,NULLIF(j->'source'->'offset'->>'decimal','')::numeric,j->>'sourceRowSha256','T4 run='||:'run'FROM st;
CREATE TEMP TABLE cls AS SELECT sp.j,em.id employee_id,bp.id period_id,CASE WHEN(j->>'sourceMultiplicity')::int > 1 THEN'duplicate_source'WHEN em.n IS DISTINCT FROM 1 THEN'employee_unmapped'WHEN bp.id IS NULL THEN'period_invalid'WHEN j->>'disposition'<>'candidate'THEN j->>'disposition'ELSE'loaded'END disposition FROM sp LEFT JOIN em ON em.employee_code=j->'source'->>'person'LEFT JOIN hr_payroll_book b ON b.legacy_scheme=(j->>'legacyScheme')::int AND b.remark='T4 run='||:'run'LEFT JOIN hr_payroll_book_period bp ON bp.book_id=b.id AND bp.period_month=make_date((j->'source'->>'year')::int,(j->'source'->>'month')::int,1);
INSERT INTO hr_payroll_legacy_snapshot(tenant_id,park_id,batch_id,book_period_id,employee_id,legacy_source_table,legacy_employee_hash,source_content_group_hash,source_multiplicity,mapping_status,gross_amount,deduction_amount,tax_amount,net_amount,source_hash,remark)SELECT :'tenant',:'park',lb.id,c.period_id,c.employee_id,replace(j->>'sourceTable','dbo.',''),encode(digest(j->'source'->>'person','sha256'),'hex'),j->>'sourceContentGroupSha256',(j->>'sourceMultiplicity')::int,'mapped',NULLIF(g->'value'->>'decimal','')::numeric,NULLIF(d->'value'->>'decimal','')::numeric,NULLIF(t->'value'->>'decimal','')::numeric,NULLIF(n->'value'->>'decimal','')::numeric,j->>'sourceRowSha256','T4 run='||:'run'FROM cls c CROSS JOIN hr_payroll_legacy_batch lb LEFT JOIN LATERAL(SELECT x g FROM jsonb_array_elements(j->'values')x WHERE x->>'systemSummary'='gross_total')a ON true LEFT JOIN LATERAL(SELECT x d FROM jsonb_array_elements(j->'values')x WHERE x->>'systemSummary'='deduction_total')aa ON true LEFT JOIN LATERAL(SELECT x t FROM jsonb_array_elements(j->'values')x WHERE x->>'systemSummary'='tax_total')aaa ON true LEFT JOIN LATERAL(SELECT x n FROM jsonb_array_elements(j->'values')x WHERE x->>'systemSummary'='net_total')aaaa ON true WHERE lb.batch_code=:'run'AND c.disposition='loaded';
DO $$BEGIN IF EXISTS(SELECT 1 FROM hr_payroll_legacy_batch WHERE batch_code=current_setting('yuzhou.run') AND status<>'unpublished')THEN RAISE EXCEPTION'item load requires unpublished batch';END IF;END$$;
INSERT INTO hr_payroll_legacy_snapshot_item(tenant_id,park_id,snapshot_id,item_version_id,legacy_column_name,value_type,is_source_null,raw_value,decimal_value,text_value,sort_no,source_hash,remark)SELECT :'tenant',:'park',s.id,v.id,x->>'legacyColumn',CASE WHEN x->'value'->>'kind'IN('decimal','zero')THEN'decimal'WHEN x->'value'->>'kind'='null'THEN COALESCE(v.value_type,'unmapped')ELSE'text'END,x->'value'->>'kind'='null',CASE WHEN x->'value'->>'kind'IN('decimal','zero')THEN x->'value'->>'decimal'WHEN x->'value'->>'kind'='text'THEN x->'value'->>'value'WHEN x->'value'->>'kind'='empty'THEN''END,CASE WHEN x->'value'->>'kind'IN('decimal','zero')THEN(x->'value'->>'decimal')::numeric END,CASE WHEN x->'value'->>'kind'='text'THEN x->'value'->>'value'WHEN x->'value'->>'kind'='empty'THEN''END,row_number()OVER(PARTITION BY s.id),encode(digest(s.source_hash||(x->>'legacyColumn'),'sha256'),'hex'),'T4 run='||:'run'FROM cls c JOIN hr_payroll_legacy_snapshot s ON s.source_content_group_hash=j->>'sourceContentGroupSha256'AND s.remark='T4 run='||:'run'CROSS JOIN LATERAL jsonb_array_elements(j->'values')x JOIN hr_payroll_book_period bp ON bp.id=s.book_period_id JOIN hr_payroll_item_definition d ON d.book_id=bp.book_id AND d.legacy_item_name=x->>'legacyColumn'JOIN hr_payroll_item_version v ON v.item_definition_id=d.id WHERE c.disposition='loaded';
DO $$BEGIN IF EXISTS((SELECT DISTINCT tenant_id,park_id,snapshot_id FROM hr_payroll_legacy_snapshot_item WHERE remark='T4 run='||current_setting('yuzhou.run') EXCEPT SELECT tenant_id,park_id,id FROM hr_payroll_legacy_snapshot WHERE remark='T4 run='||current_setting('yuzhou.run'))) OR EXISTS((SELECT DISTINCT tenant_id,park_id,item_version_id FROM hr_payroll_legacy_snapshot_item WHERE remark='T4 run='||current_setting('yuzhou.run') AND item_version_id IS NOT NULL EXCEPT SELECT tenant_id,park_id,id FROM hr_payroll_item_version WHERE remark='T4 run='||current_setting('yuzhou.run')))THEN RAISE EXCEPTION'snapshot item owner/FK verification failed';END IF;END$$;
DO $$DECLARE loaded_rows bigint; quarantined_rows bigint; loaded_items bigint; source_net numeric(20,4); loaded_source_net numeric(20,4); loaded_target_net numeric(20,4); BEGIN
 SELECT COALESCE(sum((j->>'sourceMultiplicity')::int)FILTER(WHERE disposition='loaded'),0),COALESCE(sum((j->>'sourceMultiplicity')::int)FILTER(WHERE disposition<>'loaded'),0) INTO loaded_rows,quarantined_rows FROM cls;
 SELECT count(*) INTO loaded_items FROM hr_payroll_legacy_snapshot_item WHERE remark='T4 run='||current_setting('yuzhou.run');
 IF loaded_rows<>45947 OR quarantined_rows<>145 OR loaded_items<>1074736 THEN RAISE EXCEPTION'T4 profiled accounting drift';END IF;
 SELECT COALESCE(sum(((x->'value'->>'decimal')::numeric)*(j->>'sourceMultiplicity')::int),0) INTO source_net FROM sp CROSS JOIN LATERAL jsonb_array_elements(j->'values')x WHERE x->>'systemSummary'='net_total' AND x->'value'->>'kind' IN('decimal','zero');
 SELECT COALESCE(sum(((x->'value'->>'decimal')::numeric)*(j->>'sourceMultiplicity')::int),0) INTO loaded_source_net FROM cls CROSS JOIN LATERAL jsonb_array_elements(j->'values')x WHERE disposition='loaded' AND x->>'systemSummary'='net_total' AND x->'value'->>'kind' IN('decimal','zero');
 SELECT COALESCE(sum(net_amount*source_multiplicity),0) INTO loaded_target_net FROM hr_payroll_legacy_snapshot WHERE remark='T4 run='||current_setting('yuzhou.run');
 IF loaded_source_net IS DISTINCT FROM loaded_target_net THEN RAISE EXCEPTION'T4 loaded net amount drift';END IF;
 UPDATE hr_payroll_legacy_batch SET source_amount_total=source_net,loaded_amount_total=loaded_target_net WHERE batch_code=current_setting('yuzhou.run');
END$$;
INSERT INTO hr_payroll_review_case(tenant_id,park_id,batch_id,formula_version_id,case_type,subject_hash,evidence_summary,remark)SELECT :'tenant',:'park',lb.id,f.id,'formula_unsafe',encode(digest(f.id::text,'sha256'),'hex'),'{"reason":"manual_review"}','T4 run='||:'run'FROM hr_payroll_formula_version f CROSS JOIN hr_payroll_legacy_batch lb WHERE f.remark='T4 run='||:'run'AND lb.batch_code=:'run';
WITH b AS(SELECT id FROM migration_batch WHERE run_id=:'run')INSERT INTO migration_batch_item(batch_id,domain,source_object,phase,status,extracted_count,valid_count,loaded_count,rejected_count,checksum_sha256,started_at,finished_at)SELECT id,'payroll_snapshot','dbo.salary01..35','load',CASE WHEN q > 0 THEN'quarantined'ELSE'succeeded'END,46092,46092-q,l,q,:'bh',now(),now()FROM b CROSS JOIN(SELECT COALESCE(sum((j->>'sourceMultiplicity')::int)FILTER(WHERE disposition='loaded'),0)l,COALESCE(sum((j->>'sourceMultiplicity')::int)FILTER(WHERE disposition<>'loaded'),0)q FROM cls)x;
WITH b AS(SELECT id FROM migration_batch WHERE run_id=:'run')INSERT INTO migration_batch_item(batch_id,domain,source_object,phase,status,extracted_count,valid_count,loaded_count,rejected_count,checksum_sha256,started_at,finished_at)SELECT b.id,x.domain,x.source_object,'load','succeeded',x.n,x.n,x.n,0,:'catalog',now(),now() FROM b CROSS JOIN(VALUES('payroll_membership','dbo.schemes',647),('payroll_item','dbo.salaryitems',711),('payroll_formula','dbo.salaryequal',244),('payroll_tax_rule','dbo.tax',9),('payroll_close','dbo.salarycount',1431))x(domain,source_object,n);
WITH b AS(SELECT id FROM migration_batch WHERE run_id=:'run'),i AS(SELECT id FROM migration_batch_item WHERE batch_id=(SELECT id FROM b) AND domain='payroll_snapshot')INSERT INTO migration_error(batch_id,batch_item_id,category,error_code,source_identity_sha256,redacted_evidence)SELECT b.id,i.id,'validation',upper(disposition),j->>'sourceContentGroupSha256',jsonb_build_object('multiplicity',j->>'sourceMultiplicity','table',j->>'sourceTable')FROM cls,b,i WHERE disposition<>'loaded';
WITH b AS(SELECT id FROM migration_batch WHERE run_id=:'run')INSERT INTO legacy_record_map(batch_id,source_system,source_table,source_pk_canonical,source_identity_sha256,source_row_sha256,target_table,target_id,mapping_status)SELECT b.id,'yuzhou-v10','derived',x.id::text,encode(digest(t||x.id::text,'sha256'),'hex'),h,t,x.id,'loaded'FROM b CROSS JOIN LATERAL(SELECT id,'hr_payroll_legacy_batch't,manifest_hash h FROM hr_payroll_legacy_batch WHERE batch_code=:'run'UNION ALL SELECT id,'hr_payroll_book',source_hash FROM hr_payroll_book WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_item_definition',encode(digest(id::text,'sha256'),'hex')FROM hr_payroll_item_definition WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_item_version',source_hash FROM hr_payroll_item_version WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_formula_version',expression_hash FROM hr_payroll_formula_version WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_book_period',source_hash FROM hr_payroll_book_period WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_book_membership',source_hash FROM hr_payroll_book_membership WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_tax_rule_version',source_hash FROM hr_payroll_tax_rule_version WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_legacy_snapshot',source_hash FROM hr_payroll_legacy_snapshot WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_legacy_snapshot_item',source_hash FROM hr_payroll_legacy_snapshot_item WHERE remark='T4 run='||:'run'UNION ALL SELECT id,'hr_payroll_review_case',subject_hash FROM hr_payroll_review_case WHERE remark='T4 run='||:'run')x;
ANALYZE legacy_record_map;
ANALYZE hr_payroll_legacy_snapshot_item;
DO $$DECLARE current_employee text;current_t3 text;current_runs text;current_slips text;BEGIN
 SELECT encode(digest(COALESCE(string_agg(id::text||employment_status,''ORDER BY id),''),'sha256'),'hex') INTO current_employee FROM hr_employee;
 SELECT encode(digest(COALESCE(string_agg(id::text||legacy_id,''ORDER BY id),''),'sha256'),'hex') INTO current_t3 FROM hr_employee_insurance_period;
 SELECT encode(digest(COALESCE(string_agg(id::text||status,''ORDER BY id),''),'sha256'),'hex') INTO current_runs FROM hr_payroll_run;
 SELECT encode(digest(COALESCE(string_agg(id::text||status,''ORDER BY id),''),'sha256'),'hex') INTO current_slips FROM hr_payslip;
 IF EXISTS(SELECT 1 FROM before_hash WHERE employee IS DISTINCT FROM current_employee OR t3 IS DISTINCT FROM current_t3 OR runs IS DISTINCT FROM current_runs OR slips IS DISTINCT FROM current_slips)THEN RAISE EXCEPTION'T4 modified T0/T3 or online payroll state';END IF;
END$$;
UPDATE hr_payroll_legacy_batch SET loaded_row_count=(SELECT COALESCE(sum(source_multiplicity),0)FROM hr_payroll_legacy_snapshot WHERE batch_id=hr_payroll_legacy_batch.id),quarantined_row_count=46092-(SELECT COALESCE(sum(source_multiplicity),0)FROM hr_payroll_legacy_snapshot WHERE batch_id=hr_payroll_legacy_batch.id),status='staged'WHERE batch_code=:'run';
WITH b AS(SELECT id FROM migration_batch WHERE run_id=:'run')INSERT INTO migration_check(batch_id,check_code,expected_value,actual_value,passed,evidence_sha256)SELECT id,'T4_ACCOUNTING','46092',to_jsonb((SELECT loaded_row_count+quarantined_row_count FROM hr_payroll_legacy_batch WHERE batch_code=:'run')),true,encode(digest('46092','sha256'),'hex')FROM b;
WITH b AS(SELECT id FROM migration_batch WHERE run_id=:'run')INSERT INTO migration_rollback_point(batch_id,rollback_code,reversible_scope,cleanup_manifest,evidence_sha256,verified_at)SELECT id,'T4_PAYROLL_HISTORY',jsonb_build_object('run',:'run'),'{"procedure":"rollback_yuzhou_t4_payroll_history"}',:'bh',now()FROM b;
DO $$DECLARE a record;BEGIN SELECT * INTO a FROM before_hash;IF a.employee IS DISTINCT FROM(SELECT encode(digest(COALESCE(string_agg(id::text||employment_status,''ORDER BY id),''),'sha256'),'hex')FROM hr_employee)OR a.t3 IS DISTINCT FROM(SELECT encode(digest(COALESCE(string_agg(id::text||legacy_id,''ORDER BY id),''),'sha256'),'hex')FROM hr_employee_insurance_period)OR a.runs IS DISTINCT FROM(SELECT encode(digest(COALESCE(string_agg(id::text||status,''ORDER BY id),''),'sha256'),'hex')FROM hr_payroll_run)OR a.slips IS DISTINCT FROM(SELECT encode(digest(COALESCE(string_agg(id::text||status,''ORDER BY id),''),'sha256'),'hex')FROM hr_payslip)THEN RAISE EXCEPTION'protected T0/T3/online payroll drift';END IF;END$$;
UPDATE migration_batch SET phase='verify',status='succeeded',counts=jsonb_build_object('source',46092,'loaded',(SELECT loaded_row_count FROM hr_payroll_legacy_batch WHERE batch_code=:'run'),'quarantined',(SELECT quarantined_row_count FROM hr_payroll_legacy_batch WHERE batch_code=:'run'),'items',711,'formulas',244,'closes',1431,'memberships',647,'taxRules',9),finished_at=now()WHERE run_id=:'run';COMMIT;
